joi_block.script:
hold_ticks := 0
if (all(#Front).contactSensor_contact ==| false) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 60) {
any(#Front).switch_on()
        delay(3 MIN)
any(#Front).switch_off()
        break
}
}
else {
hold_ticks = 0
}

